#!/usr/bin/env node
/**
 * Inject deploy-time build metadata into the static site tree.
 *
 * Canonical source for production is GITHUB_SHA during the Pages workflow.
 * Generated files are written into the working tree / artifact only — they are
 * not required to be committed.
 *
 * Usage:
 *   GITHUB_SHA=abc123 node scripts/inject-build-metadata.mjs
 *   WAYPOINT_BUILD_SHA=abc123 node scripts/inject-build-metadata.mjs --root ./_site
 */
import fs from "fs";
import path from "path";
import { fileURLToPath } from "url";
import { execSync } from "child_process";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const DEFAULT_ROOT = path.resolve(__dirname, "..");

const LOADER_VERSION = 2;
const LOCATION_SCHEMA = 4;
const MIGRATION_EPOCH = 3;
const MIN_RECOVERY_BUILD = "cf51ce4";

const HTML_FILES = [
  "index.html",
  "dashboard.html",
  "apps/dashboard/index.html",
  "kiosk.html",
  "debug.html",
  "status.html",
  "apps/scenes/index.html",
  "apps/photo-coach/index.html",
  "apps/photo-coach/profile/index.html",
  "apps/photo-coach/guide/index.html",
  "apps/foragecast/index.html",
  "apps/fieldry/index.html",
  "apps/shed-hunting/index.html",
  "apps/steepleaf/index.html",
  "apps/signalterrain/index.html",
  "apps/signalterrain/topics.html",
  "apps/signalterrain/graph.html",
  "apps/signalterrain/summary.html",
  "apps/signalterrain/cyber/index.html",
  "apps/signalterrain/cyber/brief.html",
  "apps/signalterrain/cyber/explorer.html",
  "apps/signalterrain/cyber/ingest-health.html",
  "apps/waypoint-volunteer/index.html",
  "apps/waypoint-volunteer/discover.html",
  "apps/waypoint-volunteer/saved/index.html",
  "apps/waypoint-volunteer/profile/index.html",
  "apps/waypoint-volunteer/impact/index.html",
  "apps/savant-sommelier/index.html",
  "apps/waypoint-scenes/index.html",
  "design-system/patterns/product-shell.html",
  "design-system/content-engine/demo.html",
  "design-system/ecosystem/product-home-shell.html"
];

const VERSIONED_ASSETS = [
  "wds-build.js",
  "wds.js",
  "wds-platform.js",
  "home-boot.js",
  "kiosk-normalize.js",
  "kiosk-boot.js",
  "kiosk.js",
  "wds-app-nav-config.js",
  "wds-app-nav.js",
  "wds-app-shell.js",
  "wds-app-shell.css",
  "studio-home.js"
];

function argValue(flag) {
  const i = process.argv.indexOf(flag);
  return i >= 0 ? process.argv[i + 1] : null;
}

function resolveRoot() {
  return path.resolve(argValue("--root") || process.env.WAYPOINT_SITE_ROOT || DEFAULT_ROOT);
}

function resolveSha() {
  const fromEnv =
    process.env.WAYPOINT_BUILD_SHA ||
    process.env.GITHUB_SHA ||
    process.env.COMMIT_SHA ||
    "";
  if (fromEnv.trim()) return fromEnv.trim();
  try {
    return execSync("git rev-parse HEAD", { cwd: DEFAULT_ROOT, encoding: "utf8" }).trim();
  } catch {
    return "local";
  }
}

function shortSha(full) {
  return String(full || "local").slice(0, 7);
}

function resolveSource() {
  if (process.env.WAYPOINT_BUILD_SOURCE) return process.env.WAYPOINT_BUILD_SOURCE;
  if (process.env.GITHUB_ACTIONS === "true") return "github-pages";
  return "local";
}

function stampHtml(file, sha) {
  if (!fs.existsSync(file)) return false;
  let html = fs.readFileSync(file, "utf8");
  let next = html
    .replace(/__WAYPOINT_BUILD_SHA__/g, sha)
    .replace(/\?v=[a-f0-9]{7,40}/gi, "?v=" + sha);

  VERSIONED_ASSETS.forEach((name) => {
    const esc = name.replace(/\./g, "\\.");
    const re = new RegExp('((?:src|href)="[^"]*' + esc + ')(?:\\?v=[^"]*)?(")', "g");
    next = next.replace(re, "$1?v=" + sha + "$2");
  });

  if (/<meta\s+name="waypoint-build"/i.test(next)) {
    next = next.replace(
      /<meta\s+name="waypoint-build"[^>]*>/i,
      '<meta name="waypoint-build" content="' + sha + '">'
    );
  } else if (/<meta\s+charset=/i.test(next)) {
    next = next.replace(
      /(<meta\s+charset=[^>]*>)/i,
      '$1\n  <meta name="waypoint-build" content="' + sha + '">'
    );
  }

  next = next.replace(/(<script src="[^"]*wds-build\.js\?v=[^"]+") defer>/g, "$1>");

  if (next !== html) {
    fs.writeFileSync(file, next, "utf8");
    return true;
  }
  return false;
}

function writeBuildInfo(root, info) {
  const jsonPath = path.join(root, "data", "build-info.json");
  fs.mkdirSync(path.dirname(jsonPath), { recursive: true });
  fs.writeFileSync(jsonPath, JSON.stringify(info, null, 2) + "\n", "utf8");
  return jsonPath;
}

function writeBuildJs(root, info) {
  const jsPath = path.join(root, "design-system", "js", "wds-build.js");
  fs.mkdirSync(path.dirname(jsPath), { recursive: true });
  const legacy = {
    commit: info.shortCommit,
    commitFull: info.commit,
    deployedAt: info.builtAt,
    locationSchema: LOCATION_SCHEMA,
    loaderVersion: LOADER_VERSION,
    migrationEpoch: MIGRATION_EPOCH,
    minRecoveryBuild: MIN_RECOVERY_BUILD,
    shortCommit: info.shortCommit,
    builtAt: info.builtAt,
    workflowRunId: info.workflowRunId,
    source: info.source
  };
  const js = `/**
 * Waypoint build metadata — generated by scripts/inject-build-metadata.mjs
 * Do not edit manually. Production values come from GITHUB_SHA at deploy time.
 */
(function (global) {
  "use strict";
  var BUILD = ${JSON.stringify(legacy, null, 2)};
  var scriptLoads = [];

  function getVersionQuery() {
    return BUILD && BUILD.commit ? "?v=" + BUILD.commit : "";
  }

  function trackScript(scriptEl) {
    if (!scriptEl || !scriptEl.src) return;
    var entry = {
      url: scriptEl.src,
      startedAt: new Date().toISOString(),
      status: "pending",
      cacheSource: "network"
    };
    scriptLoads.push(entry);
    scriptEl.addEventListener("load", function () {
      entry.status = "loaded";
      entry.loadedAt = new Date().toISOString();
    });
    scriptEl.addEventListener("error", function () {
      entry.status = "error";
      entry.loadedAt = new Date().toISOString();
    });
  }

  global.__WAYPOINT_BUILD__ = {
    commit: BUILD.commit,
    commitFull: BUILD.commitFull,
    shortCommit: BUILD.shortCommit,
    deployedAt: BUILD.deployedAt,
    builtAt: BUILD.builtAt,
    workflowRunId: BUILD.workflowRunId,
    source: BUILD.source,
    locationSchema: BUILD.locationSchema,
    loaderVersion: BUILD.loaderVersion,
    migrationEpoch: BUILD.migrationEpoch,
    minRecoveryBuild: BUILD.minRecoveryBuild
  };
  global.WDS = global.WDS || {};
  global.WDS.build = {
    info: BUILD,
    getVersionQuery: getVersionQuery,
    trackScript: trackScript,
    getScriptLoads: function () { return scriptLoads.slice(); }
  };
})(typeof window !== "undefined" ? window : global);
`;
  fs.writeFileSync(jsPath, js, "utf8");
  return jsPath;
}

function main() {
  const root = resolveRoot();
  const full = resolveSha();
  const short = shortSha(full);
  const info = {
    commit: full,
    shortCommit: short,
    builtAt: new Date().toISOString(),
    workflowRunId: process.env.GITHUB_RUN_ID || null,
    source: resolveSource(),
    // Compat fields used by older diagnostics
    commitFull: full,
    deployedAt: new Date().toISOString(),
    locationSchema: LOCATION_SCHEMA,
    loaderVersion: LOADER_VERSION,
    migrationEpoch: MIGRATION_EPOCH,
    minRecoveryBuild: MIN_RECOVERY_BUILD
  };

  let stamped = 0;
  HTML_FILES.forEach((rel) => {
    if (stampHtml(path.join(root, rel), short)) stamped += 1;
  });

  writeBuildInfo(root, info);
  writeBuildJs(root, info);

  console.log(
    JSON.stringify(
      {
        ok: true,
        root,
        shortCommit: short,
        commit: full,
        source: info.source,
        workflowRunId: info.workflowRunId,
        stampedHtml: stamped
      },
      null,
      2
    )
  );
}

main();
